config.script:
set -euo pipefail
ISSUE=${input.issue}
cd ${worktree.success.path}
git add -A
git diff --cached --quiet && { echo '没有任何改动，不建 PR'; exit 1; }
git commit -qm "fix: 关闭 #$ISSUE"
git push -qu origin HEAD
gh pr create --fill

